            WHERE p.pronamespace = 'kai'::regnamespace AND p.proname = 'organization_factual_review_enforce_coverage_scope'
              AND pg_get_function_identity_arguments(p.oid) = '' AND p.pronargs = 0
              AND md5(p.prosrc) = '5389a02820cf48bd6ea464cb1c219d0b' AND l.lanname = 'plpgsql' AND p.provolatile = 'v'
              AND pg_get_function_result(p.oid) = 'trigger' AND p.prosecdef = false AND p.prokind = 'f')
         AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'kai'::regnamespace AND p.proname = 'organization_factual_review_enforce_coverage_scope') = 1 THEN 'target' ELSE 'other' END) <> 'base')::text,
              'R05 refuses (raises "rollback refused: client_admin review decisions exist") and changes nothing while any count is above 0. Never delete, reclassify or discard these decisions to force it.'
         FROM (SELECT (CASE WHEN to_regclass('kai.evidence_review_decisions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.evidence_review_decisions WHERE decided_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) e,
              (SELECT (CASE WHEN to_regclass('kai.claim_review_decisions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.claim_review_decisions WHERE decided_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) c,
              (SELECT (CASE WHEN to_regclass('kai.coverage_review_decisions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.coverage_review_decisions WHERE decided_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) v
  UNION ALL
  SELECT 102, 'RP', 'R05_APP', 'INFO',
              'application before database',
              'not determinable from the database',
              'Before R05 the application must already serve a revision that never records a client_admin review decision (before e0022aa, for example 96653f8); otherwise the organization''s review fails with SQLSTATE 23514 after R05.'
)
SELECT seq, section, check_id, status, expected, observed, detail FROM checks
UNION ALL
SELECT 999, 'OVERALL', 'OVERALL', (SELECT status FROM checks WHERE check_id = 'R05'), 'R05 may run only when SAFE_TO_ROLL_BACK', 'counts only',
       'Run rollback/R05 only when R05 is SAFE_TO_ROLL_BACK and the application has already been moved off e0022aa or later.'
ORDER BY seq;
